import React, { useState, useEffect } from "react";
import "./RouteForm.css";

const RouteForm = ({
  onSave,
  onCancel,
  isVisible,
  route = null,
  isEditing = false,
  mapInstance = null,
}) => {
  const [formData, setFormData] = useState({
    nombre: "",
    tipo: "peatonal",
    distancia: 0,
    tiempo_estimado: 0,
    geometria: null,
    puntos_ruta: [],
  });

  const [mapClickHandler, setMapClickHandler] = useState(null);
  const [tempMarkers, setTempMarkers] = useState([]);
  const [tempLine, setTempLine] = useState(null);
  const [selectionActive, setSelectionActive] = useState(false);
  const [mapAvailable, setMapAvailable] = useState(false);
  const [minimized, setMinimized] = useState(false); // ✅ Nuevo estado para minimizar

  // ✅ Verificar si el mapa está disponible
  useEffect(() => {
    if (mapInstance && typeof window !== "undefined" && window.L) {
      setMapAvailable(true);
      console.log("✅ Mapa disponible para RouteForm");
    } else {
      setMapAvailable(false);
      console.warn("⚠️ Mapa no disponible para RouteForm");
    }
  }, [mapInstance]);

  useEffect(() => {
    if (route && isEditing) {
      setFormData({
        nombre: route.nombre || "",
        tipo: route.tipo || "peatonal",
        distancia: route.distancia || 0,
        tiempo_estimado: route.tiempo_estimado || 0,
        geometria: route.geometria || null,
        puntos_ruta: route.puntos_ruta || [],
      });
    } else {
      setFormData({
        nombre: "",
        tipo: "peatonal",
        distancia: 0,
        tiempo_estimado: 0,
        geometria: null,
        puntos_ruta: [],
      });
    }
  }, [route, isEditing]);

  // Limpiar marcadores temporales al cerrar
  useEffect(() => {
    if (!isVisible) {
      clearTempMarkers();
      removeMapClickListener();
      setMinimized(false); // ✅ Restaurar al cerrar
    }
  }, [isVisible]);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleNumberChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: parseFloat(value) || 0,
    }));
  };

  // ✅ Activar selección en el mapa y minimizar
  const handleActivateMapSelection = () => {
    if (!mapAvailable || !mapInstance) {
      alert(
        "❌ El mapa no está disponible. Espera a que el mapa se cargue completamente."
      );
      return;
    }

    if (!mapInstance.getContainer()) {
      alert("❌ El mapa aún no está listo. Intenta de nuevo en unos segundos.");
      return;
    }

    // Limpiar selección anterior
    clearTempMarkers();
    removeMapClickListener();

    // ✅ Minimizar el formulario
    setMinimized(true);

    // Cambiar cursor del mapa
    mapInstance.getContainer().style.cursor = "crosshair";
    setSelectionActive(true);

    const handler = (e) => {
      if (!e || !e.latlng) {
        console.error("Evento de mapa inválido");
        return;
      }

      const { lat, lng } = e.latlng;
      console.log("📍 Punto capturado:", { lat, lng });
      addPointToRoute(lat, lng);
    };

    mapInstance.on("click", handler);
    setMapClickHandler(() => handler);

    alert(
      "🎯 Modo selección activado: Haz clic en el mapa para agregar puntos. Mínimo 2 puntos. El formulario se ha minimizado."
    );
  };

  // ✅ Restaurar formulario
  const handleRestoreForm = () => {
    setMinimized(false);
    handleDeactivateMapSelection();
  };

  // ✅ Desactivar selección en el mapa
  const handleDeactivateMapSelection = () => {
    removeMapClickListener();
    setSelectionActive(false);
    if (mapInstance && mapInstance.getContainer()) {
      mapInstance.getContainer().style.cursor = "";
    }
  };

  // ✅ Agregar punto a la ruta
  const addPointToRoute = (lat, lng) => {
    if (!mapInstance) {
      console.error("No se puede agregar punto: mapa no disponible");
      return;
    }

    const puntoCount = formData.puntos_ruta.length;
    let tipo_punto;

    if (puntoCount === 0) {
      tipo_punto = "inicio";
    } else {
      tipo_punto = "intermedio";
    }

    const newPoint = {
      lat,
      lng,
      nombre: `Punto ${puntoCount + 1}`,
      tipo_punto: tipo_punto,
    };

    try {
      // Crear marcador temporal
      const marker = window.L.marker([lat, lng], {
        icon: window.L.divIcon({
          html: `<div style="background-color: ${
            newPoint.tipo_punto === "inicio"
              ? "#27ae60"
              : newPoint.tipo_punto === "fin"
              ? "#e74c3c"
              : "#3498db"
          }; width: 16px; height: 16px; border-radius: 50%; border: 3px solid white; box-shadow: 0 2px 6px rgba(0,0,0,0.3);"></div>`,
          iconSize: [22, 22],
          className: "temp-route-point",
        }),
      }).addTo(mapInstance);

      marker.bindPopup(`
        <div style="text-align: center;">
          <strong>${newPoint.nombre}</strong><br>
          Lat: ${lat.toFixed(6)}<br>
          Lng: ${lng.toFixed(6)}<br>
          <small>${newPoint.tipo_punto}</small>
        </div>
      `);

      // Agregar a puntos temporales
      const updatedMarkers = [...tempMarkers, marker];
      setTempMarkers(updatedMarkers);

      // Agregar a puntos de ruta
      const updatedPuntos = [
        ...formData.puntos_ruta,
        {
          orden: puntoCount + 1,
          tipo_punto: newPoint.tipo_punto,
          descripcion: `${newPoint.nombre} (${lat.toFixed(4)}, ${lng.toFixed(
            4
          )})`,
          nombre_punto: newPoint.nombre,
          coordenadas: {
            type: "Point",
            coordinates: [lng, lat],
          },
        },
      ];

      setFormData((prev) => ({
        ...prev,
        puntos_ruta: updatedPuntos,
      }));

      // Actualizar línea temporal
      updateTempLine(updatedPuntos);
    } catch (error) {
      console.error("Error al agregar punto:", error);
      alert("Error al agregar punto al mapa");
    }
  };

  // ✅ Actualizar línea temporal en el mapa
  const updateTempLine = (puntos) => {
    if (!mapInstance) return;

    if (tempLine && mapInstance.hasLayer(tempLine)) {
      mapInstance.removeLayer(tempLine);
    }

    if (puntos.length >= 2) {
      try {
        const coordinates = puntos.map((punto) => {
          const [lng, lat] = punto.coordenadas.coordinates;
          return [lat, lng];
        });

        const line = window.L.polyline(coordinates, {
          color: "#3498db",
          weight: 4,
          opacity: 0.7,
          dashArray: "5, 10",
          className: "temp-route-line",
        }).addTo(mapInstance);

        setTempLine(line);
      } catch (error) {
        console.error("Error al actualizar línea:", error);
      }
    }
  };

  // ✅ Calcular ruta basada en los puntos seleccionados
  const handleCalculateRoute = () => {
    if (formData.puntos_ruta.length < 2) {
      alert("Se necesitan al menos 2 puntos para crear una ruta");
      return;
    }

    // Crear geometría LineString
    const coordinates = formData.puntos_ruta.map(
      (punto) => punto.coordenadas.coordinates
    );

    const geometria = {
      type: "LineString",
      coordinates: coordinates,
    };

    // Calcular distancia total (aproximada)
    const distancia = calculateTotalDistance(formData.puntos_ruta);
    const tiempo_estimado = Math.round(distancia / 80); // 1.3 m/s caminata

    setFormData((prev) => ({
      ...prev,
      geometria,
      distancia,
      tiempo_estimado,
    }));

    // Desactivar selección en mapa
    handleDeactivateMapSelection();

    alert("✅ Ruta calculada exitosamente");
  };

  // ✅ Calcular distancia total de la ruta
  const calculateTotalDistance = (puntos) => {
    let totalDistance = 0;

    for (let i = 0; i < puntos.length - 1; i++) {
      const puntoA = puntos[i];
      const puntoB = puntos[i + 1];

      const [lngA, latA] = puntoA.coordenadas.coordinates;
      const [lngB, latB] = puntoB.coordenadas.coordinates;

      totalDistance += calculateDistance(latA, lngA, latB, lngB);
    }

    return Math.round(totalDistance);
  };

  // ✅ Función para calcular distancia entre dos puntos
  const calculateDistance = (lat1, lon1, lat2, lon2) => {
    const R = 6371e3; // Radio de la Tierra en metros
    const φ1 = (lat1 * Math.PI) / 180;
    const φ2 = (lat2 * Math.PI) / 180;
    const Δφ = ((lat2 - lat1) * Math.PI) / 180;
    const Δλ = ((lon2 - lon1) * Math.PI) / 180;

    const a =
      Math.sin(Δφ / 2) * Math.sin(Δφ / 2) +
      Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

    return R * c;
  };

  // ✅ Limpiar marcadores temporales
  const clearTempMarkers = () => {
    if (!mapInstance) return;

    tempMarkers.forEach((marker) => {
      if (mapInstance.hasLayer(marker)) {
        mapInstance.removeLayer(marker);
      }
    });
    setTempMarkers([]);

    if (tempLine && mapInstance.hasLayer(tempLine)) {
      mapInstance.removeLayer(tempLine);
      setTempLine(null);
    }
  };

  // ✅ Remover listener del mapa
  const removeMapClickListener = () => {
    if (mapInstance) {
      mapInstance.off("click");
      setMapClickHandler(null);

      if (mapInstance.getContainer()) {
        mapInstance.getContainer().style.cursor = "";
      }
    }
    setSelectionActive(false);
  };

  // ✅ Limpiar todos los puntos
  const handleClearPoints = () => {
    clearTempMarkers();
    removeMapClickListener();

    setFormData((prev) => ({
      ...prev,
      puntos_ruta: [],
      geometria: null,
      distancia: 0,
      tiempo_estimado: 0,
    }));
  };

  // ✅ Eliminar último punto
  const handleRemoveLastPoint = () => {
    if (formData.puntos_ruta.length === 0) return;

    // Remover último marcador
    const lastMarker = tempMarkers[tempMarkers.length - 1];
    if (lastMarker && mapInstance && mapInstance.hasLayer(lastMarker)) {
      mapInstance.removeLayer(lastMarker);
    }

    // Actualizar arrays
    const updatedMarkers = tempMarkers.slice(0, -1);
    const updatedPuntos = formData.puntos_ruta.slice(0, -1);

    setTempMarkers(updatedMarkers);
    setFormData((prev) => ({
      ...prev,
      puntos_ruta: updatedPuntos,
    }));

    // Actualizar línea
    updateTempLine(updatedPuntos);

    // Si quedan menos de 2 puntos, limpiar geometría
    if (updatedPuntos.length < 2) {
      setFormData((prev) => ({
        ...prev,
        geometria: null,
        distancia: 0,
        tiempo_estimado: 0,
      }));
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!formData.nombre || !formData.geometria) {
      alert("Nombre y ruta calculada son requeridos");
      return;
    }

    if (formData.puntos_ruta.length < 2) {
      alert("Se necesitan al menos 2 puntos para crear una ruta");
      return;
    }

    // Limpiar antes de guardar
    clearTempMarkers();
    removeMapClickListener();
    setMinimized(false); // ✅ Restaurar al guardar

    onSave(formData);
  };

  // ✅ Limpiar todo al cancelar
  const handleCancel = () => {
    clearTempMarkers();
    removeMapClickListener();
    setMinimized(false); // ✅ Restaurar al cancelar
    onCancel();
  };

  if (!isVisible) return null;

  return (
    <div className="route-form-overlay">
      <div className={`route-form-container ${minimized ? "minimized" : ""}`}>
        {minimized ? (
          // ✅ VISTA MINIMIZADA - Solo muestra información básica y botón para restaurar
          <div className="minimized-view">
            <div className="minimized-header">
              <h4>🎯 Seleccionando Puntos en el Mapa</h4>
              <button className="restore-btn" onClick={handleRestoreForm}>
                ↗️ Restaurar
              </button>
            </div>
            <div className="minimized-info">
              <div className="minimized-stats">
                <span>
                  Puntos seleccionados:{" "}
                  <strong>{formData.puntos_ruta.length}</strong>
                </span>
                {formData.puntos_ruta.length >= 2 && (
                  <span className="distance-preview">
                    Distancia aproximada:{" "}
                    <strong>
                      {calculateTotalDistance(formData.puntos_ruta)}m
                    </strong>
                  </span>
                )}
              </div>
              <div className="minimized-instructions">
                <p>💡 Haz clic en el mapa para agregar puntos</p>
                <p>✅ Mínimo 2 puntos necesarios</p>
              </div>
            </div>
          </div>
        ) : (
          // ✅ VISTA COMPLETA - Formulario normal
          <>
            <div className="route-form-header">
              <h3>{isEditing ? "✏️ Editar Ruta" : "➕ Crear Nueva Ruta"}</h3>
              <button className="close-btn" onClick={handleCancel}>
                ×
              </button>
            </div>

            <form onSubmit={handleSubmit} className="route-form">
              <div className="form-group">
                <label>Nombre de la Ruta *</label>
                <input
                  type="text"
                  name="nombre"
                  value={formData.nombre}
                  onChange={handleInputChange}
                  placeholder="Ej: Ruta desde Punto A hasta Punto B"
                  required
                />
              </div>

              <div className="form-group">
                <label>Tipo de Ruta</label>
                <select
                  name="tipo"
                  value={formData.tipo}
                  onChange={handleInputChange}>
                  <option value="peatonal">Peatonal</option>
                  <option value="vehicular">Vehicular</option>
                  <option value="accesible">Accesible</option>
                </select>
              </div>

              <div className="route-selection-section">
                <h4>🗺️ Seleccionar Puntos en el Mapa</h4>

                {!mapAvailable && (
                  <div className="map-unavailable-warning">
                    ⚠️ El mapa no está disponible. Espera a que se cargue
                    completamente.
                  </div>
                )}

                <p className="section-description">
                  {mapAvailable
                    ? "Activa la selección y haz clic en el mapa para agregar puntos de la ruta. Se necesitan al menos 2 puntos."
                    : "Esperando a que el mapa se cargue..."}
                </p>

                <div className="map-selection-controls">
                  {!selectionActive ? (
                    <button
                      type="button"
                      className="select-btn"
                      onClick={handleActivateMapSelection}
                      disabled={!mapAvailable}>
                      🎯{" "}
                      {mapAvailable
                        ? "Activar Selección en Mapa"
                        : "Mapa No Disponible"}
                    </button>
                  ) : (
                    <button
                      type="button"
                      className="deactivate-btn"
                      onClick={handleDeactivateMapSelection}>
                      ⏹️ Desactivar Selección
                    </button>
                  )}

                  <div className="point-actions">
                    <button
                      type="button"
                      className="remove-btn"
                      onClick={handleRemoveLastPoint}
                      disabled={
                        formData.puntos_ruta.length === 0 || !mapAvailable
                      }>
                      ↩️ Eliminar Último Punto
                    </button>

                    <button
                      type="button"
                      className="clear-btn"
                      onClick={handleClearPoints}
                      disabled={
                        formData.puntos_ruta.length === 0 || !mapAvailable
                      }>
                      🗑️ Limpiar Todos
                    </button>
                  </div>
                </div>

                <div className="points-counter">
                  <span>Puntos seleccionados: </span>
                  <strong>{formData.puntos_ruta.length}</strong>
                  {formData.puntos_ruta.length > 0 && (
                    <span className="points-hint">
                      (
                      {
                        formData.puntos_ruta.find(
                          (p) => p.tipo_punto === "inicio"
                        )?.nombre_punto
                      }
                      →{" "}
                      {
                        formData.puntos_ruta[formData.puntos_ruta.length - 1]
                          ?.nombre_punto
                      }
                      )
                    </span>
                  )}
                </div>

                {formData.puntos_ruta.length > 0 && (
                  <div className="selected-points">
                    <h5>Puntos de la Ruta:</h5>
                    <div className="points-list">
                      {formData.puntos_ruta.map((punto, index) => (
                        <div key={index} className="point-item">
                          <span className="point-order">{punto.orden}.</span>
                          <span className="point-name">
                            {punto.nombre_punto}
                          </span>
                          <span className="point-coords">
                            ({punto.coordenadas.coordinates[1].toFixed(4)},{" "}
                            {punto.coordenadas.coordinates[0].toFixed(4)})
                          </span>
                          <span className={`point-type ${punto.tipo_punto}`}>
                            {punto.tipo_punto}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>

              {formData.puntos_ruta.length >= 2 && (
                <div className="route-calculation-section">
                  <button
                    type="button"
                    className="calculate-btn"
                    onClick={handleCalculateRoute}>
                    🧮 Calcular Ruta
                  </button>
                </div>
              )}

              {formData.geometria && (
                <div className="route-details">
                  <h4>📊 Detalles de la Ruta Calculada</h4>

                  <div className="route-stats">
                    <div className="stat-item">
                      <span className="stat-label">Distancia Total:</span>
                      <span className="stat-value">
                        {formData.distancia} metros
                      </span>
                    </div>
                    <div className="stat-item">
                      <span className="stat-label">Tiempo Estimado:</span>
                      <span className="stat-value">
                        {formData.tiempo_estimado} minutos
                      </span>
                    </div>
                    <div className="stat-item">
                      <span className="stat-label">Número de Puntos:</span>
                      <span className="stat-value">
                        {formData.puntos_ruta.length}
                      </span>
                    </div>
                    <div className="stat-item">
                      <span className="stat-label">Tipo de Ruta:</span>
                      <span className="stat-value">{formData.tipo}</span>
                    </div>
                  </div>
                </div>
              )}

              <div className="form-actions">
                <button
                  type="button"
                  onClick={handleCancel}
                  className="cancel-btn">
                  Cancelar
                </button>
                <button
                  type="submit"
                  className="save-btn"
                  disabled={!formData.geometria}>
                  {isEditing ? "Actualizar" : "Crear"} Ruta
                </button>
              </div>
            </form>
          </>
        )}
      </div>
    </div>
  );
};

export default RouteForm;
